1	import { mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
2	import { tmpdir } from "node:os";
3	import { join } from "node:path";
4	import { afterEach, expect, test } from "vitest";
5	import { createBasketStore } from "./baskets";
6	
7	const BASKET_A = "0f3c9d6e-7a1b-4c2d-9e8f-123456789abc";
8	const BASKET_B = "6d2a1f0c-3b4e-4f5a-8c7d-0a1b2c3d4e5f";
9	
10	// The exact file of the "Reads a basket from an existing file" scenario: basket A with one karashynyard line.
11	const FILE_WITH_BASKET_A =
12	  '{"baskets":{"0f3c9d6e-7a1b-4c2d-9e8f-123456789abc":{"updatedAt":"2026-10-04T10:00:00.000Z","items":[{"productId":"karashynyard:1498486363994","quantity":2,"addedAt":"2026-10-04T10:00:00.000Z"}]}}}';
13	
14	const basketA = {
15	  updatedAt: "2026-10-04T10:00:00.000Z",
16	  items: [{ productId: "karashynyard:1498486363994", quantity: 2, addedAt: "2026-10-04T10:00:00.000Z" }],
17	};
18	
19	const dirs: string[] = [];
20	
21	/** A fresh empty temp directory per test; the store gets `<tmp>/baskets.json` as a value. */
22	function newStore() {
23	  const dir = mkdtempSync(join(tmpdir(), "baskets-"));
24	  dirs.push(dir);
25	  return { dir, file: join(dir, "baskets.json"), store: createBasketStore(join(dir, "baskets.json")) };
26	}
27	
28	function readFile(file: string): unknown {
29	  return JSON.parse(readFileSync(file, "utf8"));
30	}
31	
32	afterEach(() => {
33	  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
34	});
35	
36	test("Missing file means no baskets", async () => {
37	  const { dir, store } = newStore();
38	
39	  await expect(store.get(BASKET_A)).resolves.toBeUndefined();
40	
41	  expect(readdirSync(dir)).toEqual([]);
42	});
43	
44	test("Reads a basket from an existing file", async () => {
45	  const dir = mkdtempSync(join(tmpdir(), "baskets-"));
46	  dirs.push(dir);
47	  writeFileSync(join(dir, "baskets.json"), FILE_WITH_BASKET_A);
48	  const store = createBasketStore(join(dir, "baskets.json"));
49	
50	  await expect(store.get(BASKET_A)).resolves.toEqual(basketA);
51	});
52	
53	test("Update writes the basket to the file", async () => {
54	  const { file, store } = newStore();
55	
56	  const written = await store.update(BASKET_A, () => basketA);
57	
58	  expect(written).toEqual(basketA);
59	  expect(readFile(file)).toEqual({ baskets: { [BASKET_A]: basketA } });
60	  await expect(store.get(BASKET_A)).resolves.toEqual(basketA);
61	});
62	
63	test("Write is atomic and keeps other baskets", async () => {
64	  const dir = mkdtempSync(join(tmpdir(), "baskets-"));
65	  dirs.push(dir);
66	  writeFileSync(join(dir, "baskets.json"), FILE_WITH_BASKET_A);
67	  const store = createBasketStore(join(dir, "baskets.json"));
68	  const osioLine = { productId: "osio:6abcf192b7db2532803d266d", quantity: 1, addedAt: "2026-10-04T10:05:00.000Z" };
69	  let received: unknown = "callback not called";
70	
71	  await store.update(BASKET_B, (current) => {
72	    received = current;
73	    return { updatedAt: "2026-10-04T10:05:00.000Z", items: [...(current?.items ?? []), osioLine] };
74	  });
75	
76	  expect(received).toBeUndefined();
77	  expect(readdirSync(dir)).toEqual(["baskets.json"]);
78	  expect(readFile(join(dir, "baskets.json"))).toEqual({
79	    baskets: {
80	      [BASKET_A]: basketA,
81	      [BASKET_B]: { updatedAt: "2026-10-04T10:05:00.000Z", items: [osioLine] },
82	    },
83	  });
84	});
