export const SnapshotFileSchema = z.object({
  shop: z.object({ key: ShopKeySchema, name: z.string(), url: z.string() }),
  fetchedAt: z.string(),
  products: z.array(ProductSchema.omit({ id: true, shopKey: true, shopName: true })),
});
