  const app = new Hono();
  app.get("/api/health", (c) => c.json({ ok: true, service: "organic-catalog-api" }));
  app.route("/api/products", productsRoutes(catalog));
  app.route("/api/basket", basketRoutes(createBasketService({ store: basketStore, catalog, now })));
  return app;
}

