import { Link, Outlet } from "react-router";
import { BasketProvider, useBasket } from "./basket/BasketContext";

function BasketLink() {
  const { count } = useBasket();
  return (
    <nav>
      <Link to="/basket" className="text-sm text-emerald-700 underline">
        Кошик ({count})
      </Link>
    </nav>
